    container_type = m.group(1).strip() if m else None
    # object type: words after "two" (or a number)
    m = re.search(r'(?:two|2)\s+([a-z]+(?:\s+[a-z]+)?)', g)
    if not m:
        m = re.search(r'put\s+(?:a|an|the)\s+([a-z]+(?:\s+[a-z]+)?)', g)
    obj_type = m.group(1).strip() if m else None
    if obj_type:
        # strip trailing location hints if accidentally captured
        for w in ('in', 'on', 'to', 'from', 'with', 'into'):
            if w in obj_type:
                obj_type = obj_type.split(w)[0].strip()

    def parse_obs(text):
        """Return lists of (objname, loc) and (receptacle names)."""
        objects = []
        holders = []
        # find "On the X, you see a, b, and c."
        for mm in re.finditer(r'(?:On|In) the ([^,]+?), you see (.*?)\.', text):
            loc = mm.group(1).strip()
            items = mm.group(2)
            if items.lower().startswith('nothing'):
                continue
            items = re.sub(r'\band\b', ',', items)
            for it in items.split(','):
                it = it.strip().rstrip('.')
                if it:
                    objects.append((it, loc))
        # find "In it, you see ..." using last location
        for mm in re.finditer(r'In it, you see (.*?)\.', text):
            items = mm.group(1)
            if items.lower().startswith('nothing'):
                continue
            items = re.sub(r'\band\b', ',', items)
            # location is the receptacle mentioned in the same feedback
            locm = re.search(r'(?:The|the)\s+([a-z0-9]+\s*\d*)\s+is', text)
            loc = None
            if locm:
                loc = locm.group(1).strip()
            for it in items.split(','):
                it = it.strip().rstrip('.')
                if it and loc:
                    objects.append((it, loc))
        # room description receptacles
        for mm in re.finditer(r'\b([a-z]+[a-z]*\s*\d+)', text):
            name = mm.group(1)
            if re.match(r'^[a-z]+ \d+$', name) or re.match(r'^[a-z]+[a-z]*\d+$', name):
                holders.append(name)
        return objects, holders

    def base(name):
        return re.sub(r'\s*\d+$', '', name).strip().lower()

    def is_obj(name, typ):
        b = base(name)
        t = typ.lower()
        return b == t or b.startswith(t) or t.startswith(b)

    def is_container(name, typ):
        return base(name) == typ.lower()

    # ---- initial room scan ----
    seen = {}          # base(objtype) -> list of full names seen
    known_locs = {}    # full objname -> last known location
    containers = []    # full names of candidate containers
    to_open = []       # closed receptacles we might want to open
    inventory = []

    obs = env.observation
    objects, holders = parse_obs(obs)
    for o, loc in objects:
        known_locs[o] = loc
        seen.setdefault(base(o), []).append(o)
    for h in holders:
        if container_type and is_container(h, container_type):
            containers.append(h)
        if re.search(r'\b' + re.escape(h.split()[0]) + r'\b', obs.lower()):
            pass

    # always note all receptacles from the room text
    all_recs = []
    for mm in re.finditer(r'([a-z]+[a-z]*\s*\d+)', obs):
        all_recs.append(mm.group(1))

    def held_count():
        return len(inventory)

    def find_targets():
        """full names of objects matching obj_type that we've observed"""
        if not obj_type:
            return []
        out = []
        for b, lst in seen.items():
            if is_obj(b, obj_type):
                out.extend(lst)
        return out

    def target_container():
        if not container_type:
            return None
        for c in containers:
            return c
        for r in all_recs:
            if is_container(r, container_type):
                return r
        return None

    def go(loc):
        return env.step('go to ' + loc)

    def say(cmd):
        return env.step(cmd)

    def refresh(text):
        nonlocal obs
        obs = text
        objs, holds = parse_obs(text)
        for o, loc in objs:
            known_locs[o] = loc
            seen.setdefault(base(o), []).append(o)
        for h in holds:
            if h not in all_recs:
                all_recs.append(h)

    def open_if_needed(loc):
        # returns True if loc is open/accessible
        if re.search(r'\b' + re.escape(loc) + r'\b.*\bclosed\b', obs.lower()):
            r = env.step('open ' + loc)
            refresh(r)
            return True
        return False

    # ---- main loop ----
    # strategy:
    # 1. visit every receptacle in room; open closed ones; collect seen objects
    # 2. when we locate matching objects, pick them up and deposit in container
    # We keep a queue of locations to explore and re-visit container as needed.

    visited = set()
    queue = []
    for r in all_recs:
        queue.append(r)

    # also include the container target first so we can confirm it
    tc = target_container()
    if tc:
        queue.insert(0, tc)

    steps = 0
    max_steps = 45

    while steps < max_steps:
        # check completion
        targets = find_targets()
        if tc and len(targets) >= 2:
            # count how many are in container
            cnt = 0
            for t in targets:
                if known_locs.get(t) and is_container(known_locs[t], container_type):
                    cnt += 1
            if cnt >= 2:
                return
        if tc and held_count() >= 2:
            pass

        # if we hold a target object, deposit it
        if inventory:
            cur = inventory[0]
            if is_obj(cur, obj_type) and tc:
                r = env.step('move ' + cur + ' to ' + tc)
                refresh(r)
                inventory.pop(0)
                steps += 1
                continue
            # not useful, keep or drop later
            if not is_obj(cur, obj_type):
                # maybe drop in container anyway to free hands
                if tc:
                    r = env.step('move ' + cur + ' to ' + tc)
                    refresh(r)
                    inventory.pop(0)
                    steps += 1
                    continue

        # choose next action
        # priority: if we know a target object not yet in container and we're at/able to reach it
        picked = False
        for t in find_targets():
            loc = known_locs.get(t)
            if not loc:
                continue
            if tc and is_container(loc, container_type):
                continue
            if t == inventory[0] if inventory else False:
                continue
            # go take it
            r = go(loc)
            refresh(r)
            steps += 1
            open_if_needed(loc)
            r = env.step('take ' + t + ' from ' + loc)
            refresh(r)
            steps += 1
            if 'pick up' in r.lower() or 'you pick' in r.lower():
                inventory.append(t)
                picked = True
                break
            # failed (maybe closed); try open then take
            if 'nothing happens' in r.lower():
                open_if_needed(loc)
                r = env.step('take ' + t + ' from ' + loc)
                refresh(r)
                steps += 1
                if 'pick up' in r.lower() or 'you pick' in r.lower():
                    inventory.append(t)
                    picked = True
                    break
        if picked:
            continue

        # otherwise explore next unvisited receptacle
        if queue:
            loc = queue.pop(0)
            if loc in visited:
                continue
            visited.add(loc)
            r = go(loc)
            refresh(r)
            steps += 1
            # open if closed
            if re.search(r'\b' + re.escape(loc) + r'\b.*\bclosed\b', obs.lower()):
                r = env.step('open ' + loc)
                refresh(r)
                steps += 1
            # look to reveal contents
            r = env.step('look')
            refresh(r)
            steps += 1
            # re-add this loc later if it may change? no
            continue

        # no queue: re-scan targets again, maybe look
        r = env.step('look')
        refresh(r)
        steps += 1
        # if we have a target in hand and no container known, find one
        if not tc:
            tc = target_container()

    return
